(function(){
var ST=window.ST,BA=ST.BA,esc=ST.esc,$=ST.$,staff=ST.staff,D=BA.D;if(!staff||!$('app'))return;
var city=staff.city||'chennai',tab='todo',sel=null,draft=null;
var GPS={chennai:[13.0827,80.2707],hyderabad:[17.385,78.4867],bengaluru:[12.9716,77.5946],coimbatore:[11.0168,76.9558],kerala:[9.9312,76.2673]};
var SAMPLES=[];BA.allRaw().forEach(function(p){(p.fvimgs||[]).forEach(function(n){if(SAMPLES.indexOf(n)<0)SAMPLES.push(n)})});
function fvs(){return BA.jget('ba3_fvs',{})}function fvp(){return BA.jget('ba3_fv',{})}
function assigned(){var L=BA.allRaw().filter(function(p){return p.city===city&&p.cat!=='vehicle'}).sort(function(a,b){return (b.premium?1:0)-(a.premium?1:0)||a.days-b.days});return L.slice(0,16)}
function status(p){var s=fvs()[p.id]||{};if(fvp()[p.id])return 'submitted';return s.when?'scheduled':'assigned'}
function render(){var L=assigned(),sub=Object.keys(fvp()).map(function(id){return BA.find(id)||BA.allRaw().filter(function(x){return x.id===id})[0]}).filter(Boolean).filter(function(p){return p.city===city});
 var todo=L.filter(function(p){return status(p)==='assigned'}),sch=L.filter(function(p){return status(p)==='scheduled'});
 var tot=BA.allRaw().filter(function(p){return p.city===city}).length,seedDone=Math.round(tot*.58);
 $('app').innerHTML=ST.head('Field verification · '+esc(D.cities[city].label),'Visit the property, record what you see, take at least three photographs and submit. Your report goes live on the property page straight away, under your name.','<div style="text-align:right"><select id="cc" class="cs" style="color:var(--ink)">'+BA.ck.map(function(c){return '<option value="'+c+'"'+(c===city?' selected':'')+'>'+esc(D.cities[c].label)+'</option>'}).join('')+'</select></div>')+
 '<div class="kpis">'+ST.kpi('To visit',todo.length,'Premium and closing soonest first')+ST.kpi('Scheduled',sch.length,sch.length?'Next: '+esc(fvs()[sch[0].id].when):'None booked')+ST.kpi('Submitted by you',sub.length,'This session onward')+ST.kpi('City coverage',Math.round((seedDone+sub.length)/tot*100)+'%',(seedDone+sub.length)+' of '+tot+' properties verified')+'</div>'+
 ST.tabsHtml([['todo','To visit ('+todo.length+')'],['sch','Scheduled ('+sch.length+')'],['sub','Submitted ('+sub.length+')']],tab)+'<div class="lwg"><div id="fl"></div><div id="fd"></div></div>';
 var list=tab==='todo'?todo:tab==='sch'?sch:sub;if(!sel||!list.some(function(p){return p.id===sel}))sel=list[0]?list[0].id:null;
 $('fl').innerHTML=list.length?list.map(function(p){var s=fvs()[p.id]||{};return '<div class="sc" style="padding:14px 16px;margin-bottom:10px;cursor:pointer;'+(sel===p.id?'outline:2px solid var(--rose)':'')+'" data-p="'+p.id+'"><div style="display:flex;justify-content:space-between;gap:10px"><b>'+esc(p.short)+' · '+esc(p.loc)+'</b>'+(p.premium?ST.chip('PREMIUM','a'):'')+'</div><span style="color:var(--mute);font-size:13px">'+BA.CL[p.cat]+' · '+esc(p.size)+' · auction in '+p.days+' days'+(s.when?' · visit '+esc(s.when):'')+'</span></div>'}).join(''):'<div class="sc" style="padding:24px"><b style="font-size:19px">Nothing here</b><span>'+(tab==='sub'?'Submitted visits appear here.':'You are all caught up for this city.')+'</span></div>';
 var p=sel&&BA.allRaw().filter(function(x){return x.id===sel})[0];$('fd').innerHTML=p?detail(p):'';
 $('tabs').onclick=function(e){var b=e.target.closest('button');if(b){tab=b.dataset.t;sel=null;draft=null;render()}};$('cc').onchange=function(){city=this.value;sel=null;draft=null;render()};
 $('fl').onclick=function(e){var c=e.target.closest('[data-p]');if(c){sel=c.dataset.p;draft=null;render()}};
 if(p)wire(p)}
function detail(p){var s=fvs()[p.id]||{},done=fvp()[p.id],st=status(p);
 if(done)return '<div class="sc" style="padding:20px;position:sticky;top:76px"><small>Submitted</small><h3 style="font:800 20px var(--f);margin:6px 0">'+esc(p.short)+' · '+esc(p.loc)+'</h3><p style="margin:0 0 10px;color:var(--mute)">By '+esc(done.by)+' on '+esc(done.when)+' · Live on the property page for Pro and Premium users.</p><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px">'+done.imgs.map(function(n){return '<img src="'+(n.indexOf('data:')===0?n:'img/'+n)+'" alt="" style="width:100%;aspect-ratio:4/3;object-fit:cover;border-radius:10px">'}).join('')+'</div><div class="facts2" style="grid-template-columns:1fr 1fr;margin-top:12px"><div><small>Occupancy</small><b>'+esc(done.occ)+'</b></div><div><small>Estimated market value</small><b>'+BA.inr(done.est)+'</b></div><div><small>Landmark</small><b>'+esc(done.lm.km+' km from '+done.lm.name)+'</b></div><div><small>GPS</small><b>'+esc(done.gps)+'</b></div></div><p style="margin:12px 0 0;color:var(--mute)">'+esc(done.notes||'')+'</p><p style="margin:12px 0 0"><button class="btn out sm" data-redo="'+p.id+'">Withdraw and redo</button> <a class="btn out sm" href="property.html?id='+p.id+'&sv=1" target="_blank">Open listing ↗</a></p></div>';
 if(!draft)draft=Object.assign({imgs:[],occ:'',access:'',boundary:'',cond:'3',util:[],lit:'',lmn:'',lmk:'',est:'',notes:'',gps:''},s.draft||{});
 var d=draft;
 var head='<div class="sc" style="padding:20px"><small>'+(st==='scheduled'?'Scheduled visit · '+esc(s.when):'Assignment')+'</small><h3 style="font:800 20px var(--f);margin:6px 0 4px;letter-spacing:-.02em">'+esc(p.title)+'</h3><p style="margin:0 0 10px;color:var(--mute)">'+esc(p.bank)+' · '+esc(p.loc)+', '+esc(D.cities[p.city].label)+' · '+esc(p.pin)+' · Property '+p.id+'</p><div class="facts2" style="grid-template-columns:1fr 1fr"><div><small>Reserve</small><b>'+BA.inr(p.reserve)+'</b></div><div><small>Auction</small><b>'+esc(p.auction_full)+'</b></div><div><small>Possession per bank</small><b>'+esc(p.poss)+'</b></div><div><small>Size per notice</small><b>'+esc(p.size)+'</b></div></div></div>';
 if(st==='assigned'){var days=[1,2,3,4,5].map(function(i){var x=new Date();x.setDate(x.getDate()+i);return BA.ymd(x)});
  return head+'<div class="sc" style="padding:20px;margin-top:14px"><h3 style="font:800 17px var(--f);margin:0 0 10px">Schedule the visit</h3><div class="two" style="gap:12px;grid-template-columns:1fr 1fr"><label class="form" style="max-width:none">Date<select id="vd">'+days.map(function(x){return '<option value="'+x+'">'+new Date(x+'T00:00:00').toLocaleDateString('en-GB',{weekday:'short',day:'2-digit',month:'short'})+'</option>'}).join('')+'</select></label><label class="form" style="max-width:none">Time<select id="vt"><option>10:00 am</option><option>12:00 pm</option><option>3:00 pm</option><option>5:00 pm</option></select></label></div><p style="color:var(--mute);font-size:13px;margin:10px 0">The bank officer is informed through the portal. You can start the report on the day.</p><button class="btn" id="vgo">Confirm visit</button></div>'}
 var chk=function(n,o){return '<label class="form" style="max-width:none">'+n[0]+'<select data-f="'+n[1]+'"><option value="">Select</option>'+o.map(function(x){return '<option'+(d[n[1]]===x?' selected':'')+'>'+x+'</option>'}).join('')+'</select></label>'};
 return head+'<div class="sc" style="padding:20px;margin-top:14px"><h3 style="font:800 17px var(--f);margin:0 0 12px">Site report</h3><div class="two" style="gap:12px;grid-template-columns:1fr 1fr">'+chk(['Occupancy','occ'],['Vacant','Occupied by owner','Occupied by tenant','Unauthorised occupant'])+chk(['Access road','access'],['Wide, paved','Narrow, paved','Unpaved','No direct access'])+chk(['Boundaries match documents','boundary'],['Yes','Partly','No'])+chk(['Structure condition (1 poor, 5 good)','cond'],['1','2','3','4','5'])+'</div>'+
 '<div class="cks" style="margin:12px 0">'+['Electricity','Water','Drainage','Gas'].map(function(u){return '<label><input type="checkbox" data-u="'+u+'"'+(d.util.indexOf(u)>-1?' checked':'')+'>'+u+' connected</label>'}).join('')+'</div>'+
 '<div class="two" style="gap:12px;grid-template-columns:1fr 1fr"><label class="form" style="max-width:none">Nearest known landmark<input data-f="lmn" value="'+esc(d.lmn)+'" placeholder="e.g. Tidel Park"></label><label class="form" style="max-width:none">Distance in km<input data-f="lmk" inputmode="decimal" value="'+esc(d.lmk)+'" placeholder="e.g. 2.5"></label></div><p style="color:var(--mute);font-size:13px;margin:4px 0 12px">This is what Free and Pro users see in place of the lender and locality on Premium properties, so choose a landmark people know.</p>'+
 '<div class="two" style="gap:12px;grid-template-columns:1fr 1fr"><label class="form" style="max-width:none">Your estimate of market value (₹ lakh)<input data-f="est" inputmode="decimal" value="'+esc(d.est)+'"></label><label class="form" style="max-width:none">Litigation or notices seen on site<input data-f="lit" value="'+esc(d.lit)+'" placeholder="None seen"></label></div><label class="form" style="max-width:none;margin-top:12px">Notes for customers<textarea data-f="notes" placeholder="What a buyer should know after standing there">'+esc(d.notes)+'</textarea></label></div>'+
 '<div class="sc" style="padding:20px;margin-top:14px"><h3 style="font:800 17px var(--f);margin:0 0 4px">Photographs <span style="color:var(--mute);font-weight:600;font-size:14px">('+d.imgs.length+' added, 3 needed)</span></h3><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:12px 0">'+d.imgs.map(function(n,i){return '<div style="position:relative"><img src="'+(n.indexOf('data:')===0?n:'img/'+n)+'" alt="" style="width:100%;aspect-ratio:1;object-fit:cover;border-radius:10px"><button data-rm="'+i+'" style="position:absolute;top:4px;right:4px;border:0;border-radius:50%;width:24px;height:24px;background:#000a;color:#fff;cursor:pointer" aria-label="Remove">×</button></div>'}).join('')+'</div><div style="display:flex;gap:8px;flex-wrap:wrap"><label class="btn out sm" style="cursor:pointer">📷 Take or upload photos<input type="file" id="fup" accept="image/*" capture="environment" multiple hidden></label><button class="btn out sm" id="fsm">Add a sample photo</button></div>'+
 '<p style="margin:14px 0 4px"><b>Location:</b> '+(d.gps?esc(d.gps)+' · captured':'not captured yet')+'</p><button class="btn out sm" id="fgps">📍 Capture GPS</button></div>'+
 '<div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:14px"><button class="btn out" id="fsd">Save draft</button><button class="btn" id="fsub">Submit verification</button></div><div id="fer" class="ok" style="background:#FFE9EE;color:#9B1C47;margin-top:12px" hidden></div>'}
function shrink(file,cb){var r=new FileReader();r.onload=function(){var im=new Image();im.onload=function(){var m=560,s=Math.min(1,m/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=im.width*s;c.height=im.height*s;c.getContext('2d').drawImage(im,0,0,c.width,c.height);cb(c.toDataURL('image/jpeg',.6))};im.src=r.result};r.readAsDataURL(file)}
function sv(p){var all=fvs();all[p.id]=Object.assign(all[p.id]||{},{draft:draft});BA.jset('ba3_fvs',all)}
function wire(p){var d=draft;
 var det=$('fd');
 det.onchange=function(e){var t=e.target;if(t.dataset.f){d[t.dataset.f]=t.value}if(t.dataset.u){var i=d.util.indexOf(t.dataset.u);if(t.checked&&i<0)d.util.push(t.dataset.u);if(!t.checked&&i>-1)d.util.splice(i,1)}if(t.id==='fup'){var fs=[].slice.call(t.files),n=fs.length;fs.forEach(function(f){shrink(f,function(u){d.imgs.push(u);if(--n===0){sv(p);render()}})})}};
 det.oninput=function(e){if(e.target.dataset.f&&e.target.tagName!=='SELECT')d[e.target.dataset.f]=e.target.value};
 det.onclick=function(e){var t=e.target.closest('button');if(!t)return;
  if(t.id==='vgo'){var all=fvs();all[p.id]=Object.assign(all[p.id]||{},{when:new Date($('vd').value+'T00:00:00').toLocaleDateString('en-GB',{weekday:'short',day:'2-digit',month:'short'})+', '+$('vt').value});BA.jset('ba3_fvs',all);ST.log('Scheduled site visit for '+p.id);BA.toast('Visit scheduled');tab='sch';render()}
  else if(t.dataset.rm){d.imgs.splice(+t.dataset.rm,1);sv(p);render()}
  else if(t.id==='fsm'){var u=SAMPLES.filter(function(x){return d.imgs.indexOf(x)<0});if(u.length){d.imgs.push(u[Math.floor(Math.random()*u.length)]);sv(p);render()}}
  else if(t.id==='fgps'){var g=GPS[p.city];d.gps=(g[0]+Math.random()*.08-.04).toFixed(5)+', '+(g[1]+Math.random()*.08-.04).toFixed(5);sv(p);BA.toast('Location captured');render()}
  else if(t.id==='fsd'){sv(p);BA.toast('Draft saved')}
  else if(t.id==='fsub'){var er=[];if(d.imgs.length<3)er.push('Add at least 3 photographs');if(!d.occ)er.push('Select occupancy');if(!d.access)er.push('Select access road');if(!d.boundary)er.push('Say whether boundaries match');if(!d.gps)er.push('Capture GPS location');if(!d.lmn||!(+d.lmk>0))er.push('Add the nearest landmark and distance');if(!(+d.est>0))er.push('Add your market value estimate');
   if(er.length){$('fer').hidden=false;$('fer').innerHTML='Before you submit:<br>• '+er.join('<br>• ');return}
   var f=fvp();f[p.id]={imgs:d.imgs.slice(),occ:d.occ,access:d.access,boundary:d.boundary,cond:d.cond,util:d.util,lit:d.lit,est:+d.est,notes:d.notes,gps:d.gps,lm:{name:d.lmn,km:+d.lmk},by:staff.name,when:ST.dfmt(Date.now())};
   try{BA.jset('ba3_fv',f)}catch(x){}var lm=BA.jget('ba3_lm',{});lm[p.id]={name:d.lmn,km:+d.lmk};BA.jset('ba3_lm',lm);ST.log('Submitted field verification for '+p.id+' ('+d.imgs.length+' photos)');BA.toast('Submitted. It is now live on the property page');draft=null;tab='sub';sel=p.id;render()}
  else if(t.dataset.redo){var f2=fvp();delete f2[t.dataset.redo];BA.jset('ba3_fv',f2);ST.log('Withdrew field verification for '+t.dataset.redo);tab='todo';draft=null;render()}}}
render();
})();
